# E07 on the target, one phase per call, everything logged under C:\BC250\e07\out. Runs elevated (SSH session).
# Register names are resolved through bc250rd's reglist.txt (generated by tools/regcalc); the only offset that
# comes in from outside is -RefusedRead, a register that is deliberately on no list, resolved by regcalc on
# the lab PC.
#
#   -Phase install                      new package, gates closed by the INF
#   -Phase gate -Mmio 0|1 -Write 0|1    set the gates, restart the device, wait for stage 61, confirm the start
#   -Phase probe -Tag x                 reads through bc250kmd and through bc250rd, side by side, plus refusals
#   -Phase write -Reg0 v -Reg1 v        write both scratch registers (hex), witness through bc250rd
param(
    [Parameter(Mandatory)][ValidateSet('install', 'gate', 'probe', 'write')][string]$Phase,
    [string]$Tag = 'x',
    [int]$Mmio = 0,
    [int]$Write = 0,
    [string]$Reg0 = '',
    [string]$Reg1 = '',
    [string]$RefusedRead = '',
    [string]$Package = 'C:\BC250\e07'
)

$ErrorActionPreference = 'Continue'
$out = Join-Path $Package 'out'
New-Item -ItemType Directory -Force $out | Out-Null
$stamp = (Get-Date).ToString('HHmmss')
$log = Join-Path $out "$Phase-$Tag-$stamp.txt"
$cli = 'C:\BC250\kmd\bc250kmd_cli.exe'
$rd = 'C:\BC250\bc250rd\bc250rd_cli.exe'
$reglist = 'C:\BC250\bc250rd\reglist.txt'
$params = 'HKLM:\SYSTEM\CurrentControlSet\Services\bc250kmd\Parameters'
$hwid = 'PCI\VEN_1002&DEV_13FE'

function Say([string]$text) { $text | Tee-Object -FilePath $log -Append }
function Offset([string]$name) {
    $line = Select-String -Path $reglist -Pattern ("^" + [regex]::Escape($name) + " ") | Select-Object -First 1
    if (-not $line) { throw "$name is not in reglist.txt" }
    ($line.Line -split ' ')[1]
}
function Witness([string[]]$names) {
    # bc250rd reads a list file; give it one with just these registers
    $list = Join-Path $Package 'witness.txt'
    $names | ForEach-Object { "$_ $(Offset $_)" } | Set-Content -Path $list -Encoding ascii
    & $rd sweep $list 2>&1 | Where-Object { $_ -match '^[A-Z0-9]+\.' }
}
function Wait-Stage61 {
    foreach ($i in 1..20) {
        $p = Get-ItemProperty $params -ErrorAction SilentlyContinue
        if ($p.LastStage -eq 61) { return $true }
        Start-Sleep -Seconds 1
    }
    return $false
}
function State {
    $gpu = Get-PnpDevice -PresentOnly | Where-Object { $_.InstanceId -like "$hwid*" } | Select-Object -First 1
    $p = Get-ItemProperty $params -ErrorAction SilentlyContinue
    Say ("device   {0}   status {1}   problem {2}" -f $gpu.FriendlyName, $gpu.Status, $gpu.Problem)
    Say ("driver   {0}" -f (Get-PnpDeviceProperty -InstanceId $gpu.InstanceId -KeyName DEVPKEY_Device_DriverVersion).Data)
    Say ("stages   last {0}   history {1}   unconfirmed {2}" -f $p.LastStage, $p.StageHistory, $p.UnconfirmedStarts)
    Say ("gates    EnableMmio {0}   EnableMmioWrite {1}" -f $p.EnableMmio, $p.EnableMmioWrite)
}

Say ("time " + (Get-Date).ToString('s') + "  phase $Phase $Tag")
switch ($Phase) {
    'install' {
        pnputil /add-driver (Join-Path $Package 'bc250kmd.inf') /install 2>&1 | ForEach-Object { Say "$_" }
        if (Wait-Stage61) { & $cli confirm | ForEach-Object { Say "$_" } } else { Say 'stage 61 NOT reached' }
        State
    }
    'gate' {
        Set-ItemProperty $params -Name EnableMmio -Value $Mmio -Type DWord
        Set-ItemProperty $params -Name EnableMmioWrite -Value $Write -Type DWord
        $gpu = Get-PnpDevice -PresentOnly | Where-Object { $_.InstanceId -like "$hwid*" } | Select-Object -First 1
        Say ("disable: " + ((pnputil /disable-device "$($gpu.InstanceId)" 2>&1 | Out-String).Trim() -replace '\s+', ' '))
        Start-Sleep -Seconds 3
        Say ("enable:  " + ((pnputil /enable-device "$($gpu.InstanceId)" 2>&1 | Out-String).Trim() -replace '\s+', ' '))
        if (Wait-Stage61) { & $cli confirm | ForEach-Object { Say "$_" } } else { Say 'stage 61 NOT reached' }
        State
    }
    'probe' {
        $names = 'GC.GRBM_STATUS', 'GC.GB_ADDR_CONFIG', 'GC.CP_ME_CNTL', 'GC.SCRATCH_REG0', 'GC.SCRATCH_REG1', 'GC.GRBM_SCRATCH_REG0'
        Say '--- through bc250rd (witness)'
        Witness $names | ForEach-Object { Say "$_" }
        Say '--- through bc250kmd (escape READ_REG)'
        foreach ($n in $names) { Say ("{0,-24} {1}" -f $n, ((& $cli read (Offset $n) 2>&1) -join ' ')) }
        if ($RefusedRead) {
            Say "--- a register that is on no list ($RefusedRead): must be refused"
            Say ((& $cli read $RefusedRead 2>&1) -join ' ')
        }
        Say '--- a write to GRBM_SCRATCH_REG0 (readable, but not on the write table): must be refused at every gate setting'
        Say ((& $cli write (Offset 'GC.GRBM_SCRATCH_REG0') 0 2>&1) -join ' ')
        Say '--- witness again: nothing may have changed'
        Witness $names | ForEach-Object { Say "$_" }
        & $cli info 2>&1 | Select-String 'version|last stage|presents' | ForEach-Object { Say "$_" }
    }
    'write' {
        $names = 'GC.SCRATCH_REG0', 'GC.SCRATCH_REG1', 'GC.GRBM_SCRATCH_REG0'
        Say '--- before, through bc250rd'
        Witness $names | ForEach-Object { Say "$_" }
        Say '--- writes through bc250kmd (escape WRITE_REG, the driver reads back)'
        Say ((& $cli write (Offset 'GC.SCRATCH_REG0') $Reg0 2>&1) -join ' ')
        Say ((& $cli write (Offset 'GC.SCRATCH_REG1') $Reg1 2>&1) -join ' ')
        Say '--- after, through bc250rd (independent mapping)'
        Witness $names | ForEach-Object { Say "$_" }
        & $cli info 2>&1 | Select-String 'version|last stage|presents' | ForEach-Object { Say "$_" }
    }
}
